 `<div class="aStats">${analyticsKpi('Candidaturas no recorte',afmt(count),'Inscrições criadas no período escolhido')}${analyticsKpi('Contratações no recorte',afmt(hired),'Status atual das candidaturas filtradas')}${analyticsKpi('Conversão observada',apercent(conversion),`${hired} contratadas ÷ ${count} inscrições · coorte aberta`)}${analyticsKpi('Integração concluída',apercent(compOn),`${doneOn} de ${s.onboarding.length} tarefas · snapshot`)}${analyticsKpi('Treinamentos concluídos',apercent(learning),`${doneTraining} de ${s.learning.length} matrículas · snapshot`)}${analyticsKpi('Efetivo ativo',afmt(s.activeEmployees.length),'Fotografia do quadro atual; não filtrado por data')}</div>`+
 `<div class="aDashboardGrid">${aPanel('Evolução de candidaturas',aLine(d.monthly),'Últimos 12 meses com inscrição · dado de registro')}${aPanel('Status das candidaturas',aDonut(statuses,'inscrições'),'Participação por status atual')}</div>`+
 `<div class="aDashboardGrid">${aPanel('Pipeline atual',aChartBars(aSorted(d.stageNames),{drill:'stage'}),'Cada candidatura é contada uma vez na etapa atual')}${aPanel('Origem das candidaturas',aChartBars(aSorted(d.sourceNames),{drill:'source'}),'Ao tocar, detalhe as inscrições dessa origem')}</div>`+
 `<div class="aDashboardGrid">${aPanel('Pessoas por área',aChartBars(aSorted(d.departments),{drill:'department'}),'Efetivo ativo · quantidade atual')}${aPanel('Indicadores da jornada',`<div class="aMiniStats"><div><span>PDIs · ações executadas</span><strong>${apercent(aratio(d.pdiDone,d.pdiTotal))}</strong>${progress(aratio(d.pdiDone,d.pdiTotal)||0)}<small>${d.pdiDone} de ${d.pdiTotal} ações</small></div><div><span>Metas quantitativas atingidas</span><strong>${apercent(aratio(goalsDone,s.goals.length))}</strong>${progress(aratio(goalsDone,s.goals.length)||0)}<small>${goalsDone} de ${s.goals.length} metas</small></div></div>`,'Execução e resultados observados; sem inferir desempenho individual')}</div>`+
 aPanel('O que merece investigação',aRecommendations(d),'Sinais descritivos e próximos passos, não diagnósticos automáticos')+
 `<p class="aDisclosure">Fonte: base fictícia Nexa Tecnologia e alterações feitas neste HTML. Taxas de contratação em recortes recentes sofrem censura temporal. Períodos, vagas e origens não são filtros válidos para todos os conjuntos da jornada; a regra aplicada aparece acima.</p>`;
