 if(type==='goals')return s.goals.map(g=>({colaborador:employeeFor(g)?.name||'',area:employeeFor(g)?.department||'',meta:g.title,resultado:g.actual_value,alvo:g.target_value,atingida:Number(g.actual_value)>=Number(g.target_value)?'sim':'nao'}));
 if(type==='onboarding')return s.onboarding.map(t=>({colaborador:employeeFor(t)?.name||'',area:employeeFor(t)?.department||'',tarefa:t.title,fase:t.phase,prazo:t.due_date,concluida:t.completed_at?'sim':'nao'}));
